// Handbuchseiten für den Simulator: Abschnitt, Kurzbeschreibung (wie whatis sie zeigt) und eine gekürzte Hilfe.
// Die Kurzbeschreibungen stammen aus den NAME-Abschnitten der englischen Handbuchseiten von Debian 12.

export interface Seite { sek: number; kurz: string; text: string; }

export const SEITEN: Record<string, Seite[]> = {
  ls: [{ sek: 1, kurz: 'list directory contents', text: '-l lang, -a auch versteckte, -A ohne . und .., -h lesbare Größen, -d Verzeichnis selbst, -R rekursiv,\n-t nach Zeit, -S nach Größe, -r umgekehrt, -1 eine Datei pro Zeile, -F Typzeichen anhängen' }],
  cp: [{ sek: 1, kurz: 'copy files and directories', text: 'cp QUELLE ZIEL, cp QUELLE… VERZEICHNIS\n-r / -R rekursiv, -a Archiv (rekursiv, Rechte und Zeiten behalten), -p Rechte und Zeiten behalten,\n-i vor dem Überschreiben fragen, -n nie überschreiben, -v ausführlich' }],
  mv: [{ sek: 1, kurz: 'move (rename) files', text: 'mv QUELLE ZIEL, mv QUELLE… VERZEICHNIS\n-i fragen, -n nie überschreiben, -v ausführlich, -f nie fragen' }],
  rm: [{ sek: 1, kurz: 'remove files or directories', text: '-r / -R rekursiv, -f ohne Rückfrage und ohne Fehler bei fehlenden Dateien, -i vor jedem Löschen fragen, -v ausführlich' }],
  mkdir: [{ sek: 1, kurz: 'make directories', text: '-p Elternverzeichnisse mit anlegen, kein Fehler wenn vorhanden; -m MODUS Rechte setzen; -v ausführlich' }],
  rmdir: [{ sek: 1, kurz: 'remove empty directories', text: 'Löscht nur leere Verzeichnisse. -p auch die leer gewordenen Elternverzeichnisse' }],
  touch: [{ sek: 1, kurz: 'change file timestamps', text: 'Legt fehlende Dateien leer an und setzt sonst die Zeit auf jetzt.\n-t [[JJ]JJ]MMTThhmm[.ss] bestimmte Zeit, -d "2 days ago" Zeit als Text, -a nur Zugriffszeit, -m nur Änderungszeit' }],
  file: [{ sek: 1, kurz: 'determine file type', text: 'Erkennt den Typ am Inhalt (magic), nicht an der Endung.' }],
  find: [{ sek: 1, kurz: 'search for files in a directory hierarchy', text: 'find [START…] [AUSDRUCK]\n-name MUSTER, -iname, -type f|d|l, -size [+-]N[ckMG], -mtime [+-]N (Tage), -mmin, -newer DATEI,\n-user, -group, -perm MODUS|-MODUS|/MODUS, -empty, -maxdepth N, ! oder -not\nAktionen: -print (Standard), -ls, -delete, -exec BEFEHL {} \\; oder {} +' }],
  tar: [{ sek: 1, kurz: 'an archiving utility', text: 'c anlegen, x auspacken, t auflisten, f DATEI Archivdatei, v ausführlich,\nz gzip, j bzip2, J xz, -C VERZEICHNIS dorthin wechseln\nBeispiele: tar czf a.tar.gz ordner/   tar tzf a.tar.gz   tar xzf a.tar.gz -C /tmp' }],
  gzip: [{ sek: 1, kurz: 'compress or expand files', text: 'gzip DATEI ersetzt DATEI durch DATEI.gz. -d entpacken (wie gunzip), -c auf die Standardausgabe, -k Original behalten, -1 schnell bis -9 klein' }],
  gunzip: [{ sek: 1, kurz: 'compress or expand files', text: 'Entpackt DATEI.gz zu DATEI. Wie gzip -d.' }],
  bzip2: [{ sek: 1, kurz: 'a block-sorting file compressor, v1.0.8', text: 'Wie gzip, Endung .bz2. -d entpacken, -k behalten, -c Standardausgabe' }],
  xz: [{ sek: 1, kurz: 'Compress or decompress .xz and .lzma files', text: 'Wie gzip, Endung .xz, meist die kleinsten Dateien. -d entpacken, -k behalten, -c Standardausgabe' }],
  zcat: [{ sek: 1, kurz: 'compress or expand files', text: 'Gibt den entpackten Inhalt einer .gz-Datei aus, ohne sie zu verändern. Ebenso bzcat (.bz2) und xzcat (.xz).' }],
  cpio: [{ sek: 1, kurz: 'copy files to and from archives', text: '-o Archiv erzeugen (Dateinamen von stdin), -i auspacken, -t auflisten, -d Verzeichnisse anlegen, -v ausführlich\nBeispiel: find ordner | cpio -o > a.cpio   cpio -idv < a.cpio' }],
  dd: [{ sek: 1, kurz: 'convert and copy a file', text: 'dd if=QUELLE of=ZIEL bs=BLOCKGRÖSSE count=ANZAHL\nBeispiel: dd if=/dev/zero of=leer.img bs=1M count=10\nVorsicht: of=/dev/sdX überschreibt das Gerät ohne Rückfrage.' }],
  cat: [{ sek: 1, kurz: 'concatenate files and print on the standard output', text: '-n Zeilen nummerieren, -A Steuerzeichen sichtbar ($ am Zeilenende, ^I für Tab)' }],
  tac: [{ sek: 1, kurz: 'concatenate and print files in reverse', text: 'Wie cat, aber mit der letzten Zeile zuerst.' }],
  head: [{ sek: 1, kurz: 'output the first part of files', text: '-n N die ersten N Zeilen (Standard 10), -n -N alle außer den letzten N, -c N Bytes' }],
  tail: [{ sek: 1, kurz: 'output the last part of files', text: '-n N die letzten N Zeilen (Standard 10), -n +N ab Zeile N, -f weiter beobachten, -c N Bytes' }],
  less: [{ sek: 1, kurz: 'opposite of more', text: 'Blättern: Leertaste, b zurück, /muster suchen, n weiter, q beenden. (Im Simulator wird der Text einfach ausgegeben.)' }],
  wc: [{ sek: 1, kurz: 'print newline, word, and byte counts for each file', text: '-l Zeilen, -w Wörter, -c Bytes, -m Zeichen' }],
  nl: [{ sek: 1, kurz: 'number lines of files', text: 'Nummeriert Zeilen, leere Zeilen standardmäßig nicht. -b a alle Zeilen, -w Breite, -s Trenner' }],
  sort: [{ sek: 1, kurz: 'sort lines of text files', text: '-n numerisch, -h menschliche Größen (2K, 1G), -r umgekehrt, -u doppelte entfernen, -f Groß/klein egal,\n-t ZEICHEN Feldtrenner, -k N[,M] nach Feld N sortieren, -o DATEI Ausgabe in Datei' }],
  uniq: [{ sek: 1, kurz: 'report or omit repeated lines', text: 'Fasst nur direkt aufeinanderfolgende gleiche Zeilen zusammen, darum meist nach sort.\n-c zählen, -d nur doppelte, -u nur einmalige, -i Groß/klein egal' }],
  cut: [{ sek: 1, kurz: 'remove sections from each line of files', text: '-d ZEICHEN Trenner (Standard Tab), -f LISTE Felder, -c LISTE Zeichen, -b LISTE Bytes, -s Zeilen ohne Trenner weglassen\nLISTE: 1,3 oder 2-4 oder 3-' }],
  paste: [{ sek: 1, kurz: 'merge lines of files', text: 'Setzt Zeilen mehrerer Dateien nebeneinander. -d ZEICHEN Trenner, -s Zeilen einer Datei zu einer verbinden' }],
  tr: [{ sek: 1, kurz: 'translate or delete characters', text: 'Liest nur von der Standardeingabe!\ntr a-z A-Z ersetzen, -d löschen, -s Wiederholungen zusammenfassen, Klassen wie [:upper:] [:digit:] [:space:]' }],
  od: [{ sek: 1, kurz: 'dump files in octal and other formats', text: '-c Zeichen, -t x1 Hex-Bytes, -A d|x|o|n Adressformat, -N N nur N Bytes. Ohne Option: oktal in Zwei-Byte-Wörtern' }],
  split: [{ sek: 1, kurz: 'split a file into pieces', text: 'split [OPTION] DATEI [PRÄFIX]. -l N Zeilen je Teil (Standard 1000), -b N Bytes (1K, 1M), -d Ziffern statt Buchstaben\nTeile heißen xaa, xab … oder PRÄFIXaa …; zusammensetzen mit cat xa* > ganz' }],
  md5sum: [{ sek: 1, kurz: 'compute and check MD5 message digest', text: 'md5sum DATEI zeigt die Prüfsumme. -c LISTE prüft Dateien gegen eine Liste. Ebenso sha256sum und sha512sum.' }],
  sha256sum: [{ sek: 1, kurz: 'compute and check SHA256 message digest', text: 'Wie md5sum, mit SHA-256. -c LISTE prüft.' }],
  sha512sum: [{ sek: 1, kurz: 'compute and check SHA512 message digest', text: 'Wie md5sum, mit SHA-512. -c LISTE prüft.' }],
  sed: [{ sek: 1, kurz: 'stream editor for filtering and transforming text', text: "s/ALT/NEU/ ersetzen (g alle, i Groß/klein egal), /MUSTER/d löschen, N,Md Zeilen löschen, p drucken mit -n,\n-i in der Datei ändern, -E erweiterte reguläre Ausdrücke, -e mehrere Befehle\nBeispiel: sed -n '/^lena/p' /etc/passwd" }],
  grep: [{ sek: 1, kurz: 'print lines that match patterns', text: '-i Groß/klein egal, -v umkehren, -c zählen, -n Zeilennummern, -l nur Dateinamen, -r rekursiv, -w ganze Wörter,\n-x ganze Zeile, -o nur Treffer, -E erweitert (wie egrep), -F feste Zeichenkette (wie fgrep)' }],
  egrep: [{ sek: 1, kurz: 'print lines that match patterns', text: 'Veraltet, entspricht grep -E.' }],
  fgrep: [{ sek: 1, kurz: 'print lines that match patterns', text: 'Veraltet, entspricht grep -F.' }],
  tee: [{ sek: 1, kurz: 'read from standard input and write to standard output and files', text: '-a anhängen statt überschreiben. Typisch: befehl | sudo tee /etc/datei' }],
  xargs: [{ sek: 1, kurz: 'build and execute command lines from standard input', text: '-n N höchstens N Argumente je Aufruf, -I {} Platzhalter, -0 Nullbyte als Trenner (zu find -print0), -r nichts tun bei leerer Eingabe' }],
  ps: [{ sek: 1, kurz: 'report a snapshot of the current processes.', text: 'ps aux (BSD-Stil), ps -ef (Unix-Stil), ps -u BENUTZER, ps -p PID, ps -C NAME,\nps -eo pid,ni,comm eigene Spalten, --sort=-%cpu sortieren' }],
  top: [{ sek: 1, kurz: 'display Linux processes', text: 'Laufende Anzeige. Tasten: q beenden, k Prozess beenden, r renice, M nach Speicher, P nach CPU. -b Batchmodus, -n N Durchläufe' }],
  free: [{ sek: 1, kurz: 'Display amount of free and used memory in the system', text: '-h lesbar, -m MiB, -g GiB' }],
  uptime: [{ sek: 1, kurz: 'Tell how long the system has been running.', text: 'Zeigt Uhrzeit, Laufzeit, Benutzer und die Last der letzten 1, 5 und 15 Minuten. -p nur die Laufzeit' }],
  pgrep: [{ sek: 1, kurz: 'look up, signal, or wait for processes based on name and other attributes', text: 'pgrep MUSTER gibt PIDs aus. -l mit Namen, -a mit Befehlszeile, -u BENUTZER, -f in der ganzen Befehlszeile suchen' }],
  pkill: [{ sek: 1, kurz: 'look up, signal, or wait for processes based on name and other attributes', text: 'Wie pgrep, schickt aber ein Signal (Standard SIGTERM). pkill -9 MUSTER' }],
  killall: [{ sek: 1, kurz: 'kill processes by name', text: 'killall NAME schickt SIGTERM an alle Prozesse mit genau diesem Namen. -9 SIGKILL, -i fragen' }],
  watch: [{ sek: 1, kurz: 'execute a program periodically, showing output fullscreen', text: 'watch -n SEKUNDEN BEFEHL wiederholt den Befehl (Standard alle 2 Sekunden). Strg+C beendet.' }],
  nice: [{ sek: 1, kurz: 'run a program with modified scheduling priority', text: 'nice -n N BEFEHL startet mit Nettigkeit N (Standard +10). Bereich -20 (höchste Priorität) bis 19 (niedrigste).\nNur root darf negative Werte setzen. Ohne Befehl: zeigt die aktuelle Nettigkeit.' }],
  renice: [{ sek: 1, kurz: 'alter priority of running processes', text: 'renice -n N -p PID, renice -n N -u BENUTZER. Normale Benutzer dürfen die Nettigkeit nur erhöhen.' }],
  nohup: [{ sek: 1, kurz: 'run a command immune to hangups, with output to a non-tty', text: 'nohup BEFEHL & läuft weiter, wenn das Terminal geschlossen wird. Ausgabe landet in nohup.out.' }],
  screen: [{ sek: 1, kurz: 'screen manager with VT100/ANSI terminal emulation', text: 'screen startet eine Sitzung, Strg+A d löst sich, screen -ls listet, screen -r verbindet wieder' }],
  tmux: [{ sek: 1, kurz: 'terminal multiplexer', text: 'tmux startet eine Sitzung, Strg+B d löst sich, tmux ls listet, tmux attach verbindet wieder' }],
  kill: [{ sek: 1, kurz: 'send a signal to a process', text: 'kill PID schickt SIGTERM (15). kill -9 PID SIGKILL, kill -1 SIGHUP, kill -l listet Signale.\nIn der Bash ist kill eingebaut und versteht auch %JOBNUMMER.' }],
  bash: [{ sek: 1, kurz: 'GNU Bourne-Again SHell', text: 'Eingebaut sind unter anderem cd, echo, export, set, unset, alias, type, history, jobs, fg, bg, kill, umask, source.\nVerlauf: ~/.bash_history, !! letzter Befehl, !N Befehl Nummer N, !text letzter Befehl mit diesem Anfang.\nStart: /etc/profile und ~/.profile für Login-Shells, ~/.bashrc für interaktive Shells.' }],
  which: [{ sek: 1, kurz: 'locate a command', text: 'Zeigt, welche Datei aus PATH ausgeführt würde. -a alle Treffer. Kennt keine Aliase und keine eingebauten Befehle, dafür gibt es type.' }],
  whereis: [{ sek: 1, kurz: 'locate the binary, source, and manual page files for a command', text: 'Zeigt Programm und Handbuchseiten eines Befehls.' }],
  uname: [{ sek: 1, kurz: 'print system information', text: '-a alles, -s Kernelname, -n Rechnername, -r Kernelversion, -v Bau-Version, -m Hardware, -o Betriebssystem' }],
  sysctl: [{ sek: 8, kurz: 'configure kernel parameters at runtime', text: 'sysctl SCHLÜSSEL zeigt, sysctl -w SCHLÜSSEL=WERT setzt (root), -a alle, -n nur Wert,\n-p [DATEI] Datei laden (ohne Datei /etc/sysctl.conf), --system alle Dateien aus /etc/sysctl.d, /run/sysctl.d,\n/usr/lib/sysctl.d und /etc/sysctl.conf. Schlüssel entsprechen Dateien unter /proc/sys: net.ipv4.ip_forward = /proc/sys/net/ipv4/ip_forward' }],
  'sysctl.conf': [{ sek: 5, kurz: 'sysctl preload/configuration file', text: 'Zeilen SCHLÜSSEL = WERT, Kommentare mit # oder ;. Ein - vor dem Schlüssel: Fehler ignorieren.' }],
  'sysctl.d': [{ sek: 5, kurz: 'Configure kernel parameters at boot', text: 'Dateien *.conf in /etc/sysctl.d, /run/sysctl.d, /usr/lib/sysctl.d. Gleicher Name in /etc überdeckt /usr/lib.\nAlle Dateien werden nach Namen sortiert gelesen, spätere Einträge gewinnen. Angewendet von systemd-sysctl beim Start.' }],
  udevadm: [{ sek: 8, kurz: 'udev management tool', text: 'info -a -n GERÄT: Attribute für Regeln (mit allen Eltern), info -q property -n GERÄT: Umgebung,\nmonitor [--kernel|--udev|--property]: Ereignisse mitlesen, trigger [--action=add]: Ereignisse auslösen,\ncontrol --reload: Regeln neu lesen, test /sys/...: Regeln probehalber anwenden, settle: warten.' }],
  udev: [{ sek: 7, kurz: 'Dynamic device management', text: 'Regeln in /lib/udev/rules.d (Paket), /etc/udev/rules.d (Admin, gewinnt bei gleichem Namen), /run/udev/rules.d.\nNur Dateien mit der Endung .rules, nach Namen sortiert. Vergleichen: ==, != · Zuweisen: =, +=, -=, :=\nKERNEL, SUBSYSTEM, DRIVER, ATTR{x}: das Gerät selbst · KERNELS, SUBSYSTEMS, DRIVERS, ATTRS{x}: ein einziges Elterngerät\nZuweisen: NAME (nur Netzwerk), SYMLINK, OWNER, GROUP, MODE, RUN, ENV{x}' }],
  dkms: [{ sek: 8, kurz: 'Dynamic Kernel Module Support', text: 'Baut Module außerhalb des Kernels für jeden installierten Kernel neu. Quellen in /usr/src/NAME-VERSION mit dkms.conf.\nadd NAME/VERSION, build, install, status, remove NAME/VERSION --all, autoinstall [-k KERNEL]. Baum: /var/lib/dkms' }],
  depmod: [{ sek: 8, kurz: 'Generate modules.dep and map files.', text: 'depmod [-a] [VERSION] schreibt /lib/modules/VERSION/modules.dep (Abhängigkeiten) und modules.alias.\nNötig, nachdem man ein Modul von Hand nach /lib/modules kopiert hat. -n gibt nur aus.' }],
  'modprobe.d': [{ sek: 5, kurz: 'Configuration directory for modprobe', text: 'Dateien *.conf in /etc/modprobe.d, /run/modprobe.d, /lib/modprobe.d. Befehle:\nalias NAME MODUL · options MODUL PARAM=WERT · blacklist MODUL (nicht per Alias laden) · install MODUL BEFEHL · remove MODUL BEFEHL · softdep MODUL pre: … post: …' }],
  'modules-load.d': [{ sek: 5, kurz: 'Configure kernel modules to load at boot', text: 'Dateien *.conf in /etc/modules-load.d, /run/modules-load.d, /usr/lib/modules-load.d: ein Modulname pro Zeile.\nAuf Debian liest dieselbe Stelle auch /etc/modules (Verknüpfung modules.conf).' }],
  modules: [{ sek: 5, kurz: 'kernel modules to load at boot time', text: '/etc/modules auf Debian: ein Modulname pro Zeile, optional mit Parametern.' }],
  patch: [{ sek: 1, kurz: 'apply a diff file to an original', text: 'patch -pN < DATEI: N führende Pfadteile abschneiden (bei a/ und b/: -p1). -i DATEI statt <, --dry-run nur prüfen,\n-R zurücknehmen. Gepackte Patches: xz -dc patch.xz | patch -p1. Fehlschläge landen in DATEI.rej.' }],
  diff: [{ sek: 1, kurz: 'compare files line by line', text: 'diff ALT NEU · -u unified (für patch), -r rekursiv, -N fehlende Dateien als leer behandeln, -q nur ob verschieden\nBeispiel: diff -ruN alt/ neu/ > fix.patch' }],
  install: [{ sek: 1, kurz: 'copy files and set attributes', text: 'install [OPTION]… QUELLE ZIEL · install [OPTION]… QUELLE… VERZEICHNIS · install -d VERZEICHNIS…\n-m MODUS Rechte (Standard rwxr-xr-x), -o BESITZER, -g GRUPPE (nur root), -d Verzeichnisse anlegen,\n-D fehlende Ordner von ZIEL anlegen, -t VERZEICHNIS Ziel vorab, -s strip, -v ausführlich' }],
  named: [{ sek: 8, kurz: 'Internet domain name server', text: 'named [-c DATEI] [-u BENUTZER] [-t VERZEICHNIS] [-f|-g] [-d STUFE] [-v|-V]\n-c Konfiguration (Debian /etc/bind/named.conf, Red Hat /etc/named.conf), -u nach dem Start als BENUTZER weiterlaufen,\n-t chroot in VERZEICHNIS, -f im Vordergrund, -g im Vordergrund mit Meldungen auf stderr, -v Version.\nSignale: SIGHUP lädt neu wie rndc reload, SIGTERM und SIGINT beenden sauber.' }],
  'named.conf': [{ sek: 5, kurz: 'configuration file for named', text: 'Anweisungen enden mit ;, Blöcke in { } enden mit };. Kommentare: //, #, /* */.\nacl NAME { … }; · options { directory, listen-on, allow-query, allow-recursion, allow-transfer, forwarders, forward, recursion, version, dnssec-validation, validate-except }; · logging { channel …; category …; }; · key NAME { algorithm; secret; }; · server ADRESSE { keys { NAME; }; }; · include "DATEI"; · view NAME { match-clients …; zone …; };\nzone "NAME" { type primary|secondary|forward|hint; file "…"; primaries { … }; forwarders { … }; allow-transfer { … }; also-notify { … }; notify yes|no; masterfile-format text|raw; dnssec-policy NAME; };' }],
  'named-checkconf': [{ sek: 1, kurz: 'named configuration file syntax checking tool', text: 'named-checkconf [-z] [-p] [-t VERZEICHNIS] [DATEI]\nOhne Ausgabe und mit Rückgabecode 0, wenn alles stimmt. -z lädt zusätzlich alle Hauptzonen zur Probe,\n-p gibt die Konfiguration aufgeräumt aus, -t liest relativ zum chroot-Verzeichnis.' }],
  'named-checkzone': [{ sek: 1, kurz: 'zone file validation tool', text: 'named-checkzone [-f FORMAT] [-D] [-o DATEI] ZONE DATEI\nPrüft die Zonendatei wie named beim Laden: Syntax, SOA, NS mit Adressen, CNAME neben anderen Daten.\n-f text|raw Eingabeformat, -D die Zone geordnet ausgeben, -o DATEI dorthin schreiben. Rückgabecode 0 = geladen.' }],
  'named-compilezone': [{ sek: 1, kurz: 'zone file converting tool', text: 'named-compilezone [-f FORMAT] [-F FORMAT] -o DATEI ZONE QUELLE\n-f Eingabeformat, -F Ausgabeformat (text, raw), -o Zieldatei, - für die Standardausgabe.\nPrüft wie named-checkzone und schreibt die Zone im gewünschten Format.' }],
  rndc: [{ sek: 8, kurz: 'name server control utility', text: 'rndc [-s SERVER] [-k DATEI] BEFEHL · Schlüssel /etc/bind/rndc.key bzw. /etc/rndc.key, TCP-Port 953\nstatus · reload [ZONE] · reconfig (Konfiguration, nur neue Zonen) · flush · flushname NAME · dumpdb [-cache|-zones|-all] (named_dump.db)\nquerylog [on|off] · zonestatus ZONE · notify ZONE · refresh ZONE · retransfer ZONE · stop · halt' }],
  'rndc-confgen': [{ sek: 8, kurz: 'rndc key generation tool', text: 'rndc-confgen -a schreibt einen neuen Schlüssel nach rndc.key, ohne -a gibt es rndc.conf und den Teil für named.conf aus.' }],
  'tsig-keygen': [{ sek: 8, kurz: 'TSIG key generation tool', text: 'tsig-keygen [-a ALGORITHMUS] [NAME] · Standard hmac-sha256, Name tsig-key\nGibt einen fertigen key-Block für named.conf aus: key "NAME" { algorithm …; secret "…"; };' }],
  'dnssec-keygen': [{ sek: 1, kurz: 'DNSSEC key generation tool', text: 'dnssec-keygen [-a ALGORITHMUS] [-b BITS] [-f KSK] [-K VERZEICHNIS] ZONE\nAlgorithmen u. a. ECDSAP256SHA256 (13), RSASHA256 (8), ED25519 (15). Ohne -f KSK entsteht ein ZSK.\nSchreibt Kzone.+AAA+KENNUNG.key (öffentlich, DNSKEY) und .private. Seit 9.13 keine HMAC-Schlüssel mehr (dafür tsig-keygen).' }],
  'dnssec-signzone': [{ sek: 1, kurz: 'DNSSEC zone signing tool', text: 'dnssec-signzone [-S] [-o ZONE] [-K VERZEICHNIS] [-k KSK] [-N keep|increment|unixtime] DATEI [ZSK…]\n-S sucht die Schlüssel selbst (smart signing), -o Name der Zone. Schreibt DATEI.signed und dsset-ZONE. mit dem DS.\nSignaturen gelten standardmäßig 30 Tage, danach neu signieren.' }],
  dig: [{ sek: 1, kurz: 'DNS lookup utility', text: 'dig [@SERVER] [-x ADRESSE] [-t TYP] [-c KLASSE] [-k DATEI] [-y ALG:NAME:GEHEIM] NAME [TYP] [+OPTION…]\n+short nur die Antwort, +noall +answer nur der Abschnitt ANSWER, +norec ohne Rekursion, +trace von der Wurzel an,\n+dnssec mit Signaturen, +tcp. TYP: A, AAAA, MX, NS, SOA, PTR, TXT, ANY, AXFR. Flags: qr, aa, rd, ra, ad.' }],
  host: [{ sek: 1, kurz: 'DNS lookup utility', text: 'host [-t TYP] [-a] [-l] [-v] NAME [SERVER] · host ADRESSE fragt nach dem PTR · -l listet die Zone (AXFR)' }],
  nslookup: [{ sek: 1, kurz: 'query Internet name servers interactively', text: 'nslookup [-type=TYP] NAME [SERVER] · ohne Argumente interaktiv: server ADRESSE, set type=MX, exit' }],
  apache2: [{ sek: 8, kurz: 'Apache Hypertext Transfer Protocol Server', text: 'Auf Debian nicht direkt aufrufen, sondern über apache2ctl oder systemctl (die Variablen aus /etc/apache2/envvars fehlen sonst).\n-t Syntax prüfen, -S virtuelle Hosts, -M Module, -v/-V Version, -f DATEI, -D NAME. Red Hat: httpd mit denselben Optionen.' }],
  httpd: [{ sek: 8, kurz: 'Apache Hypertext Transfer Protocol Server', text: 'httpd [-t] [-S] [-M] [-v] [-V] [-f DATEI] [-k start|stop|restart|graceful] · Konfiguration /etc/httpd/conf/httpd.conf, conf.d/*.conf, conf.modules.d/*.conf' }],
  apache2ctl: [{ sek: 8, kurz: 'Apache HTTP server control interface', text: 'apache2ctl configtest|-t · -S (virtuelle Hosts) · -M (Module) · start|stop|restart|graceful|graceful-stop · status (braucht www-browser)\nliest vorher /etc/apache2/envvars. apachectl ist auf Debian ein Link darauf, auf Red Hat das Gegenstück.' }],
  apachectl: [{ sek: 8, kurz: 'Apache HTTP server control interface', text: 'Siehe apache2ctl. Red Hat: apachectl configtest, apachectl graceful.' }],
  a2ensite: [{ sek: 8, kurz: 'enable or disable an apache2 site / virtual host', text: 'a2ensite NAME legt /etc/apache2/sites-enabled/NAME.conf als Link auf sites-available an, a2dissite entfernt ihn. Danach systemctl reload apache2.' }],
  a2enmod: [{ sek: 8, kurz: 'enable or disable an apache2 module', text: 'a2enmod MODUL verlinkt mods-available/MODUL.load und .conf nach mods-enabled, beachtet Abhängigkeiten (# Depends) und Konflikte (MPMs). a2dismod schaltet ab. Danach systemctl restart apache2.' }],
  a2enconf: [{ sek: 8, kurz: 'enable or disable an apache2 configuration file', text: 'a2enconf NAME verlinkt conf-available/NAME.conf nach conf-enabled, a2disconf entfernt den Link.' }],
  a2query: [{ sek: 1, kurz: 'retrieve runtime configuration from a local Apache 2 HTTP server', text: 'a2query -M (aktives MPM) · -m [MODUL] · -s [SITE] · -c [CONF] · -v (Version)' }],
  htpasswd: [{ sek: 1, kurz: 'Manage user files for basic authentication', text: 'htpasswd [-c] [-B|-m|-s] DATEI BENUTZER · -b DATEI BENUTZER PASSWORT · -n (nur ausgeben) · -D (löschen) · -v (prüfen)\n-c legt die Datei neu an und löscht dabei vorhandene Einträge. Standard ist MD5 ($apr1$), -B bcrypt.' }],
  'apache2.conf': [{ sek: 5, kurz: 'Hauptkonfiguration von Apache auf Debian', text: 'Direktiven: ServerName, ServerAlias, ServerAdmin, DocumentRoot, Listen, Include(Optional), ErrorLog, LogLevel, LogFormat, CustomLog, Timeout, KeepAlive, MaxKeepAliveRequests, KeepAliveTimeout, User, Group, AllowOverride, Options, AccessFileName, ServerTokens, ServerSignature, TraceEnable\nContainer: <VirtualHost ADRESSE:PORT>, <Directory PFAD>, <Location URL>, <Files NAME>, <IfModule MODUL>, <RequireAll>, <RequireAny>\nZugriff: Require all granted|denied, ip, host, local, valid-user, user, group · Anmeldung: AuthType Basic, AuthName, AuthUserFile, AuthGroupFile\nMPM: StartServers, MinSpareServers, MaxSpareServers, MinSpareThreads, MaxSpareThreads, ThreadsPerChild, MaxRequestWorkers, ServerLimit, MaxConnectionsPerChild\nTLS: SSLEngine, SSLCertificateFile, SSLCertificateKeyFile, SSLCertificateChainFile, SSLCACertificateFile, SSLCACertificatePath, SSLProtocol, SSLCipherSuite, SSLHonorCipherOrder' }],
  openssl: [{ sek: 1, kurz: 'OpenSSL command line program', text: 'genrsa [-aes256] -out KEY BITS · genpkey -algorithm RSA -out KEY · rsa -in KEY [-check] [-noout] [-modulus] [-out KEY]\nreq -new -key KEY -out CSR -subj "/C=DE/O=…/CN=NAME" [-addext "subjectAltName=DNS:…"] · req -x509 -newkey rsa:2048 -noenc -keyout KEY -out CRT -days N · req -in CSR -noout -text\nx509 -req -in CSR -CA CA.crt -CAkey CA.key [-CAcreateserial] [-copy_extensions copy] [-extfile F] -days N -out CRT · x509 -in CRT -noout -subject -issuer -dates -text -ext subjectAltName -modulus -fingerprint -checkend S\nverify [-CAfile CA] [-untrusted ZWISCHEN] CRT · s_client -connect HOST:PORT [-servername NAME] [-showcerts] [-tls1_2|-tls1_3] [-CAfile CA]\npasswd -apr1|-6 PW · rand -hex N · version' }],
  'CA.pl': [{ sek: 1, kurz: 'friendlier interface for OpenSSL certificate programs', text: '/usr/lib/ssl/misc/CA.pl (Debian) bzw. /etc/pki/tls/misc/CA.pl (Paket openssl-perl): -newca legt ./demoCA an, -newreq erzeugt Schlüssel und Antrag, -sign unterschreibt newreq.pem, -verify prüft. Im Simulator nicht nachgebildet.' }],
  'update-ca-certificates': [{ sek: 8, kurz: 'update /etc/ssl/certs and ca-certificates.crt', text: 'Nimmt *.crt aus /usr/local/share/ca-certificates/ (und /usr/share/ca-certificates/ laut /etc/ca-certificates.conf) in /etc/ssl/certs/ca-certificates.crt auf. Red Hat: update-ca-trust mit /etc/pki/ca-trust/source/anchors/.' }],
  curl: [{ sek: 1, kurz: 'transfer a URL', text: 'curl [-s] [-S] [-i|-I] [-v] [-L] [-f] [-o DATEI] [-w FORMAT] [-X METHODE] [-H "Kopf: Wert"] [-u USER:PW] [-x PROXY] [-U USER:PW] [-k] [--cacert CA] [--resolve HOST:PORT:IP] [--tlsv1.2] [--tls-max 1.2] URL\n-w "%{http_code}" gibt den Status aus. Umgebung: http_proxy, https_proxy, no_proxy.\nCodes: 6 Name unbekannt, 7 keine Verbindung, 22 Fehler mit -f, 35 TLS-Handshake, 56 Proxy, 60 Zertifikat nicht geprüft.' }],
  nginx: [{ sek: 8, kurz: '"HTTP and reverse proxy server, mail proxy server"', text: 'nginx -t (prüfen) · -T (prüfen und ausgeben) · -s reload|stop|quit|reopen · -c DATEI · -v/-V\nKonfiguration /etc/nginx/nginx.conf, conf.d/*.conf, sites-enabled/* · Blöcke: events, http, server, location, upstream\nserver: listen, server_name, root, index, try_files, return, allow, deny, auth_basic, auth_basic_user_file, ssl_certificate, ssl_certificate_key, ssl_protocols · location: proxy_pass, proxy_set_header, alias' }],
  squid: [{ sek: 8, kurz: 'proxy caching server', text: 'squid -k parse|check|reconfigure|rotate|shutdown · -z (Cache-Ordner anlegen) · -f DATEI · -v\nKonfiguration /etc/squid/squid.conf (Debian: eigene Regeln in conf.d/*.conf) · Protokolle /var/log/squid/access.log, cache.log' }],
  'squid.conf': [{ sek: 5, kurz: 'Konfiguration von Squid', text: 'acl NAME TYP WERTE… · Typen: src, dst, dstdomain, dstdom_regex, port, method, proto, time, url_regex, urlpath_regex, browser, proxy_auth, maxconn\nhttp_access allow|deny [!]ACL… (UND in der Zeile, erste passende Zeile gilt, ohne Treffer das Gegenteil der letzten) · http_port 3128\nauth_param basic program /usr/lib/squid/basic_ncsa_auth DATEI · auth_param basic realm TEXT · cache_mem 256 MB · cache_dir ufs /var/spool/squid MB L1 L2 · maximum_object_size · refresh_pattern · delay_pools' }],
  basic_ncsa_auth: [{ sek: 8, kurz: 'NCSA httpd-style password file authentication helper for Squid', text: 'basic_ncsa_auth PASSWORTDATEI liest Zeilen „BENUTZER PASSWORT“ von stdin und antwortet OK oder ERR. Die Datei hat das Format von htpasswd.' }],
  rsync: [{ sek: 1, kurz: 'a fast, versatile, remote (and local) file-copying tool', text: 'rsync [OPTION]… QUELLE… [BENUTZER@]RECHNER:ZIEL · rsync [OPTION]… QUELLE ZIEL\n-a Archiv (= -rlptgoD), -v ausführlich, -n trocken, -z packen, -h lesbare Zahlen, -i Änderungen auflisten,\n--delete im Ziel löschen, was in der Quelle fehlt, --exclude=MUSTER, -e ssh, --link-dest=DIR\nQUELLE/ mit Schrägstrich: Inhalt kopieren, ohne: den Ordner selbst. Nur eine Quelle: Inhalt auflisten.' }],
  mt: [{ sek: 1, kurz: 'control magnetic tape drive operation', text: 'mt [-f GERÄT] BEFEHL [ANZAHL] · ohne -f: $TAPE, sonst /dev/tape\nstatus, rewind, fsf N vor über N Dateimarken, bsf N zurück (danach vor der Marke), asf N absolut,\neod ans Ende der Daten, weof N Dateimarken schreiben, erase löschen, offline/eject auswerfen, load einlegen' }],
  'mt-st': [{ sek: 1, kurz: 'control magnetic tape drive operation', text: 'Siehe mt.' }],
  st: [{ sek: 4, kurz: 'SCSI tape device', text: '/dev/st0 spult beim Schließen zurück (rewinding), /dev/nst0 nicht (non-rewinding).\nJedes Schreiben bis zum Schließen ergibt eine Datei auf dem Band, abgeschlossen mit einer Dateimarke.' }],
  agetty: [{ sek: 8, kurz: 'alternative Linux getty', text: 'Öffnet ein Terminal, zeigt /etc/issue und /etc/issue.d/*.issue und startet login.\n--show-issue zeigt die Datei mit ersetzten Escapes im aktuellen Terminal, --issue-file DATEI eine andere Datei\nEscapes: \\n Rechner, \\l Terminal, \\r Kernel, \\m Architektur, \\s System, \\d Datum, \\t Zeit, \\U Benutzer, \\4 IPv4' }],
  issue: [{ sek: 5, kurz: 'prelogin message and identification file', text: '/etc/issue: Text, den agetty vor dem Login-Prompt zeigt, mit Escapes (siehe agetty).\n/etc/issue.net: für Anmeldungen übers Netz (telnet, sshd mit Banner /etc/issue.net, dort ohne Escapes).' }],
  motd: [{ sek: 5, kurz: 'message of the day', text: '/etc/motd zeigt pam_motd nach einer erfolgreichen Anmeldung. Debian führt zuvor /etc/update-motd.d/* aus\n(Ergebnis in /run/motd.dynamic). ~/.hushlogin unterdrückt die Meldung.' }],
  wall: [{ sek: 1, kurz: 'write a message to all users', text: 'wall [-n] [-g GRUPPE] [NACHRICHT | DATEI] · ohne Argument von der Standardeingabe\nBenutzer mit mesg n bekommen nur Nachrichten von root.' }],
  mesg: [{ sek: 1, kurz: 'display (or do not display) messages from other users', text: 'mesg zeigt den Stand, mesg n sperrt write und wall anderer Benutzer, mesg y erlaubt sie wieder' }],
  make: [{ sek: 1, kurz: 'GNU make utility to maintain groups of programs', text: 'make [ZIEL …] liest das Makefile im aktuellen Ordner. -C ORDNER vorher dorthin wechseln, -jN N Aufgaben gleichzeitig,\nNAME=WERT setzt Variablen. Im Kernelbaum zeigt make help alle Ziele.' }],
  'update-initramfs': [{ sek: 8, kurz: 'generate an initramfs image', text: '-c -k VERSION neu anlegen, -u [-k VERSION|all] aktualisieren, -d -k VERSION löschen.\nEinstellungen: /etc/initramfs-tools/initramfs.conf, zusätzliche Module: /etc/initramfs-tools/modules' }],
  mkinitramfs: [{ sek: 8, kurz: 'low-level tool for generating an initramfs image', text: 'mkinitramfs -o /boot/initrd.img-VERSION VERSION. Meist ruft man update-initramfs auf, das mkinitramfs benutzt.' }],
  lsinitramfs: [{ sek: 8, kurz: 'list content of an initramfs image', text: 'lsinitramfs /boot/initrd.img-VERSION, -l ausführlich.' }],
  dracut: [{ sek: 8, kurz: 'low-level tool for generating an initramfs/initrd image', text: 'Red Hat, SUSE, Fedora: dracut -f [BILD] [VERSION], ohne Angabe für den laufenden Kernel nach /boot/initramfs-$(uname -r).img.\n--list-modules, Einstellungen in /etc/dracut.conf und /etc/dracut.conf.d/. Inhalt anzeigen: lsinitrd. mkinitrd ist dort ein Wrapper für dracut.' }],
  lsdev: [{ sek: 8, kurz: 'display information about installed hardware', text: 'Liest /proc/interrupts, /proc/ioports und /proc/dma und zeigt je Gerät DMA, IRQ und I/O-Ports. Paket procinfo.' }],
  lshw: [{ sek: 1, kurz: 'list hardware', text: 'Am besten als root. -short Übersicht, -C KLASSE nur eine Klasse (network, disk, storage, display, memory …), -businfo Bus-Adressen.' }],
  modinfo: [{ sek: 8, kurz: 'Show information about a Linux Kernel module', text: 'modinfo MODUL oder DATEI.ko: Datei, Beschreibung, Abhängigkeiten, vermagic, Parameter (parm). -p nur Parameter, -F FELD nur ein Feld.' }],
  insmod: [{ sek: 8, kurz: 'Simple program to insert a module into the Linux Kernel', text: 'insmod DATEI.ko [PARAM=WERT]: lädt genau diese Datei, ohne Abhängigkeiten und ohne /etc/modprobe.d.' }],
  rmmod: [{ sek: 8, kurz: 'Simple program to remove a module from the Linux Kernel', text: 'rmmod MODUL entlädt ein Modul, das niemand benutzt (lsmod: Used by 0). Abhängigkeiten bleiben geladen.' }],
  lsmod: [{ sek: 8, kurz: 'Show the status of modules in the Linux Kernel', text: 'Formatiert /proc/modules: Name, Größe, Zahl der Nutzer und die Module, die es benutzen.' }],
  dmesg: [{ sek: 1, kurz: 'print or control the kernel ring buffer', text: '-T Uhrzeit, -l err,warn nur Stufen, -w mitlesen, -H lesbar. Auf Debian nur für root (kernel.dmesg_restrict = 1).' }],
  kmod: [{ sek: 8, kurz: 'Program to manage Linux Kernel modules', text: 'lsmod, modprobe, insmod, rmmod, modinfo und depmod sind Verknüpfungen auf kmod. kmod list wie lsmod.' }],
  'initramfs.conf': [{ sek: 5, kurz: 'configuration file for mkinitramfs', text: 'MODULES=most|dep|netboot|list, COMPRESS=gzip|bzip2|lz4|lzma|lzop|xz|zstd' }],
  man: [{ sek: 1, kurz: 'an interface to the system reference manuals', text: 'man [ABSCHNITT] SEITE. -k WORT sucht in den Kurzbeschreibungen (wie apropos), -f SEITE zeigt die Kurzbeschreibung (wie whatis).\nAbschnitte: 1 Benutzerbefehle, 2 Systemaufrufe, 3 Bibliotheksfunktionen, 4 Gerätedateien, 5 Dateiformate,\n6 Spiele, 7 Verschiedenes, 8 Verwaltungsbefehle für root, 9 Kernelroutinen' }],
  vi: [{ sek: 1, kurz: 'Vi IMproved, a programmer\'s text editor', text: 'Normalmodus: h j k l, w b, 0 $, gg G, x, dd, yy, p, u, /muster, ?muster, n N\nEinfügen: i a o O, zurück mit Esc. Befehlszeile: :w :q :q! :wq :x ZZ :w! :e!' }],
  passwd: [{ sek: 1, kurz: 'change user password', text: 'Ändert das Passwort des Benutzers.' }, { sek: 5, kurz: 'the password file', text: '/etc/passwd: NAME:x:UID:GID:KOMMENTAR:HEIMATVERZEICHNIS:SHELL, eine Zeile pro Konto. Das x verweist auf /etc/shadow.' }],
  shadow: [{ sek: 5, kurz: 'shadowed password file', text: '/etc/shadow: NAME:PASSWORT-HASH:LETZTE ÄNDERUNG:MIN:MAX:WARNEN:… Nur für root lesbar.' }],
  crontab: [{ sek: 1, kurz: 'maintain crontab files for individual users (Vixie Cron)', text: 'crontab -e bearbeiten, -l anzeigen, -r löschen' }, { sek: 5, kurz: 'tables for driving cron', text: 'Minute Stunde Tag Monat Wochentag Befehl' }],
  hosts: [{ sek: 5, kurz: 'static table lookup for hostnames', text: 'IP-Adresse  Name  [Aliase]' }],
  fstab: [{ sek: 5, kurz: 'static information about the filesystems', text: 'GERÄT EINHÄNGEPUNKT TYP OPTIONEN DUMP PASS' }],
  regex: [{ sek: 7, kurz: 'POSIX.2 regular expressions', text: 'Grundlegend (BRE): . beliebiges Zeichen, * beliebig oft, ^ Anfang, $ Ende, [abc] eines davon, [^abc] keines davon,\n\\{n,m\\} n bis m mal, \\( \\) Gruppe, \\| oder (GNU).\nErweitert (ERE, grep -E): + mindestens einmal, ? höchstens einmal, {n,m}, ( ), | ohne Backslash.\nKlassen: [:alpha:] [:digit:] [:alnum:] [:upper:] [:lower:] [:space:] [:punct:], immer in eckigen Klammern: [[:digit:]]' }],
  signal: [{ sek: 7, kurz: 'overview of signals', text: '1 SIGHUP, 2 SIGINT (Strg+C), 9 SIGKILL (nicht abfangbar), 15 SIGTERM (Standard von kill), 18 SIGCONT, 19 SIGSTOP, 20 SIGTSTP (Strg+Z)' }],
  hier: [{ sek: 7, kurz: 'description of the filesystem hierarchy', text: '/bin /sbin /usr/bin /usr/sbin Programme, /etc Konfiguration, /home Benutzer, /var veränderliche Daten, /tmp temporär' }],
  intro: [{ sek: 1, kurz: 'introduction to user commands', text: 'Einführung in Abschnitt 1.' }, { sek: 2, kurz: 'introduction to system calls', text: 'Einführung in Abschnitt 2.' }, { sek: 8, kurz: 'introduction to administration and privileged commands', text: 'Einführung in Abschnitt 8.' }],
  printf: [{ sek: 1, kurz: 'format and print data', text: "printf FORMAT [ARGUMENT…]: %s Text, %d Zahl, \\n neue Zeile. Anders als echo hängt printf keinen Zeilenumbruch an." }, { sek: 3, kurz: 'formatted output conversion', text: 'C-Funktion printf(3).' }],
  date: [{ sek: 1, kurz: 'print or set the system date and time', text: 'date +%F zeigt das Datum als JJJJ-MM-TT.' }],
  sleep: [{ sek: 1, kurz: 'delay for a specified amount of time', text: 'sleep N wartet N Sekunden.' }],
  env: [{ sek: 1, kurz: 'run a program in a modified environment', text: 'Ohne Argument: alle Umgebungsvariablen. env VAR=wert befehl: Befehl mit geänderter Umgebung starten. -i leere Umgebung.' }],
  fdisk: [{ sek: 8, kurz: 'manipulate disk partition table', text: '-l Partitionstabellen anzeigen (braucht root)' }],
  modprobe: [{ sek: 8, kurz: 'Add and remove modules from the Linux Kernel', text: 'modprobe MODUL lädt mit Abhängigkeiten, -r entfernt, -v ausführlich, -n nur so tun' }],
  shutdown: [{ sek: 8, kurz: 'Halt, power off or reboot the machine', text: '-h ausschalten, -r neu starten, -c abbrechen, Zeit: now, +MINUTEN, hh:mm' }],
  'update-rc.d': [{ sek: 8, kurz: 'install and remove System-V style init script links', text: 'update-rc.d NAME defaults legt die Links in /etc/rcN.d anhand des LSB-Kopfes an.\nupdate-rc.d NAME disable [RUNLEVEL] macht S-Links zu K-Links, enable dreht das um.\nupdate-rc.d -f NAME remove löscht alle Links, ohne -f nur, wenn das Skript schon fehlt.' }],
  chkconfig: [{ sek: 8, kurz: 'updates and queries runlevel information for system services', text: 'chkconfig --list [NAME] zeigt die Runlevel. chkconfig --add NAME liest die Zeile # chkconfig: RUNLEVEL START STOP.\nchkconfig --level 35 NAME on|off schaltet einzelne Runlevel, ohne --level 2345. chkconfig --del NAME.\nFür native systemd-Dienste leitet chkconfig an systemctl weiter.' }],
  telinit: [{ sek: 8, kurz: 'change SysV runlevel', text: 'telinit N wechselt in Runlevel N (0 aus, 1/S Einzelbenutzer, 6 Neustart).\ntelinit q liest /etc/inittab neu ein. Unter systemd übersetzt telinit in systemctl isolate runlevelN.target.' }],
  runlevel: [{ sek: 8, kurz: 'print previous and current SysV runlevel', text: 'Zeigt vorigen und aktuellen Runlevel, etwa „N 2“ (N = keiner vorher).' }],
  inittab: [{ sek: 5, kurz: 'format of the inittab file used by the sysv-compatible init process', text: 'Zeilen: Kennung:Runlevel:Aktion:Befehl.\nAktionen: initdefault, sysinit, boot, bootwait, wait, once, respawn, ctrlaltdel, powerfail, off.\nNach Änderungen: telinit q.' }],
  service: [{ sek: 8, kurz: 'run a System V init script', text: 'service NAME start|stop|restart|status ruft /etc/init.d/NAME auf (unter systemd: systemctl).\nservice --status-all zeigt alle Skripte mit [ + ], [ - ] oder [ ? ].' }],
  'systemd-delta': [{ sek: 1, kurz: 'Find overridden configuration files', text: 'Zeigt Dateien in /etc und /run, die Dateien aus /usr/lib ersetzen oder ergänzen.\n[OVERRIDDEN] ganz ersetzt, [EXTENDED] Drop-ins, [MASKED] auf /dev/null, [REDIRECTED] Link, [EQUIVALENT] gleich.\n--type=extended,overridden filtert.' }],
  efibootmgr: [{ sek: 8, kurz: 'manipulate the UEFI Boot Manager', text: 'Ohne Option: BootCurrent, BootOrder, Einträge. -v mit Pfaden.\n-o 0000,0002 BootOrder setzen, -n 0002 nur nächster Start, -N BootNext löschen.\n-c -d PLATTE -p PART -L NAME -l \\EFI\\x\\y.efi Eintrag anlegen, -b NNNN -B löschen, -b NNNN -a/-A ein/aus.' }],
  chroot: [{ sek: 8, kurz: 'run command or interactive shell with special root directory', text: 'chroot VERZEICHNIS [BEFEHL] macht VERZEICHNIS zum neuen /. Vorher /dev, /proc und /sys mit mount --bind einhängen.\nexit kehrt zurück.' }],
  'grub-install': [{ sek: 8, kurz: 'install GRUB to a device', text: 'BIOS: grub-install /dev/sda (in den MBR bzw. die BIOS-Boot-Partition).\nUEFI: grub-install --target=x86_64-efi --efi-directory=/boot/efi --bootloader-id=debian, legt auch den NVRAM-Eintrag an.\n--removable schreibt nach \\EFI\\BOOT\\BOOTX64.EFI ohne NVRAM.' }],
  'update-grub': [{ sek: 8, kurz: 'stub for grub-mkconfig -o /boot/grub/grub.cfg', text: 'Erzeugt /boot/grub/grub.cfg aus /etc/default/grub und /etc/grub.d/. Red Hat: grub2-mkconfig -o /boot/grub2/grub.cfg.' }],
  fsck: [{ sek: 8, kurz: 'check and repair a Linux filesystem', text: 'fsck GERÄT ruft fsck.TYP auf. -f erzwingt die Prüfung, -n ändert nichts, -y beantwortet alles mit ja.\nNur auf ausgehängten Dateisystemen. Das 6. Feld der fstab legt die Reihenfolge beim Start fest.' }],
  extlinux: [{ sek: 1, kurz: 'install the SYSLINUX bootloader on an ext2/3/4, btrfs or xfs filesystem', text: 'extlinux --install /boot/extlinux schreibt ldlinux.sys und ldlinux.c32. Konfiguration: extlinux.conf.' }],
  syslinux: [{ sek: 1, kurz: 'install the SYSLINUX bootloader on a FAT filesystem', text: 'syslinux --install /dev/sdb1. Konfiguration: syslinux.cfg. Familie: syslinux (FAT), extlinux, isolinux (ISO 9660), pxelinux (Netz).' }],
  tftp: [{ sek: 1, kurz: 'Trivial File Transfer Protocol client', text: 'tftp HOST -c get DATEI holt eine Datei, wie es ein PXE-Client beim Start tut.' }],
  xorriso: [{ sek: 1, kurz: 'creates, loads, manipulates and writes ISO 9660 filesystem images', text: 'xorriso -as mkisofs -isohybrid-mbr /usr/lib/ISOLINUX/isohdpfx.bin -b isolinux/isolinux.bin -c isolinux/boot.cat\n  -no-emul-boot -boot-load-size 4 -boot-info-table -eltorito-alt-boot -e images/efiboot.img -no-emul-boot\n  -isohybrid-gpt-basdat -o NEU.iso QUELLVERZEICHNIS' }],
  bootctl: [{ sek: 1, kurz: 'Control EFI firmware boot settings and manage boot loader', text: 'bootctl install, status, list. Einträge: /boot/efi/loader/entries/*.conf, Standard in loader/loader.conf.' }],
  dumpe2fs: [{ sek: 8, kurz: 'dump ext2/ext3/ext4 file system information', text: 'Zeigt Superblock und Blockgruppen. -h nur den Superblock. -o superblock=32768 -o blocksize=4096 liest eine Sicherungskopie.' }],
  debugfs: [{ sek: 8, kurz: 'ext2/ext3/ext4 file system debugger', text: 'debugfs GERÄT öffnet interaktiv (nur lesend), -w schreibend, -R "BEFEHL" für einen einzelnen Befehl.\nBefehle: ls -l, cd, stat DATEI, cat, dump DATEI ZIEL, lsdel, undel, stats, quit.' }],
  btrfs: [{ sek: 8, kurz: 'a toolbox to manage btrfs filesystems', text: 'btrfs filesystem show|df|usage · btrfs subvolume create|list|show|delete PFAD · btrfs subvolume snapshot [-r] QUELLE ZIEL · btrfs scrub start|status.' }],
  'btrfs-convert': [{ sek: 8, kurz: 'convert from ext2/3/4 or reiserfs filesystem to btrfs in-place', text: 'btrfs-convert GERÄT (ausgehängt). Das alte Dateisystem bleibt im Subvolume ext2_saved. -r macht die Umwandlung rückgängig.' }],
  xfs_info: [{ sek: 8, kurz: 'display XFS filesystem geometry information', text: 'xfs_info EINHÄNGEPUNKT oder GERÄT: Allocation Groups (agcount), Blockgröße, Log.' }],
  xfsdump: [{ sek: 8, kurz: 'XFS filesystem incremental dump utility', text: 'xfsdump -l STUFE -L SITZUNG -M MEDIUM -f DATEI QUELLE. Stufe 0 = alles, n = seit der letzten kleineren Stufe.' }],
  xfsrestore: [{ sek: 8, kurz: 'XFS filesystem incremental restore utility', text: 'xfsrestore -f DATEI ZIEL zurückspielen · -t Inhalt zeigen · -I Inventar · -r Stufen nacheinander.' }],
  mdadm: [{ sek: 8, kurz: 'manage MD devices aka Linux Software RAID', text: '--create /dev/md0 --level=1 --raid-devices=2 GERÄTE [--spare-devices=N] · --detail /dev/md0 · --detail --scan (Zeilen für mdadm.conf) · --examine GERÄT · /dev/md0 --fail X --remove X --add Y · --grow --raid-devices=N · --stop · --assemble --scan · --zero-superblock · --monitor --scan [--oneshot]' }],
  'mdadm.conf': [{ sek: 5, kurz: 'configuration for management of Software RAID with mdadm', text: 'Debian: /etc/mdadm/mdadm.conf, Red Hat: /etc/mdadm.conf. DEVICE partitions · ARRAY /dev/md0 UUID=… · MAILADDR root (Warnungen von mdadm --monitor). Danach update-initramfs -u bzw. dracut -f.' }],
  sfdisk: [{ sek: 8, kurz: 'display or manipulate a disk partition table', text: '-d GERÄT gibt die Tabelle als Skript aus · sfdisk ZIEL < skript schreibt sie · sfdisk -d /dev/sdc | sfdisk /dev/sdf kopiert sie · --part-type GERÄT NR TYP ändert den Typ (fd RAID, 8e LVM)' }],
  pvcreate: [{ sek: 8, kurz: 'Initialize physical volume(s) for use by LVM', text: 'pvcreate GERÄT… schreibt das LVM-Label. Anzeigen: pvs, pvdisplay, pvscan. pvremove löscht das Label wieder, pvresize passt an eine größere Partition an.' }],
  pvs: [{ sek: 8, kurz: 'Display information about physical volumes', text: 'Kurzübersicht: PV, VG, Attr, PSize, PFree. Ausführlich: pvdisplay. Ebenso vgs und lvs.' }],
  vgs: [{ sek: 8, kurz: 'Display information about volume groups', text: 'VG, #PV, #LV, #SN, VSize, VFree. Ausführlich: vgdisplay.' }],
  lvs: [{ sek: 8, kurz: 'Display information about logical volumes', text: 'LV, VG, Attr, LSize, Origin, Data%. Attr: o Origin, s Snapshot, a aktiv, o (6. Stelle) geöffnet, I ungültiger Snapshot.' }],
  lvdisplay: [{ sek: 8, kurz: 'Display information about a logical volume', text: 'LV Path, LV Status (available/NOT available), LV Size, Current LE, Block device 254:N, bei Snapshots COW-table size und Allocated to snapshot.' }],
  vgcreate: [{ sek: 8, kurz: 'Create a volume group', text: 'vgcreate NAME PV… · -s GRÖSSE setzt die Extent-Größe (Standard 4 MiB). Noch nicht initialisierte Geräte macht vgcreate selbst zu PVs.' }],
  vgextend: [{ sek: 8, kurz: 'Add physical volumes to a volume group', text: 'vgextend VG PV… nimmt weitere PVs in die VG auf.' }],
  vgreduce: [{ sek: 8, kurz: 'Remove physical volume(s) from a volume group', text: 'vgreduce VG PV entfernt ein leeres PV. Belegte Extents vorher mit pvmove verschieben.' }],
  pvmove: [{ sek: 8, kurz: 'Move extents from one physical volume to another', text: 'pvmove QUELLE [ZIEL] verschiebt belegte Extents im laufenden Betrieb, ohne ZIEL auf die übrigen PVs der VG.' }],
  vgrename: [{ sek: 8, kurz: 'Rename a volume group', text: 'vgrename ALT NEU. Danach fstab und gegebenenfalls Bootloader anpassen, wenn sie /dev/ALT/… nennen.' }],
  vgchange: [{ sek: 8, kurz: 'Change volume group attributes', text: '-ay aktiviert alle LVs der VG (legt /dev/VG/LV und /dev/mapper/VG-LV an), -an deaktiviert sie. Ohne VG-Namen gilt es für alle.' }],
  lvcreate: [{ sek: 8, kurz: 'Create a logical volume', text: 'lvcreate -L 20G -n NAME VG · -l 100%FREE · -l 50%VG · Snapshot: lvcreate -s -L 2G -n NAME VG/LV' }],
  lvextend: [{ sek: 8, kurz: 'Add space to a logical volume', text: '-L 30G (Zielgröße) · -L +10G (dazu) · -l +100%FREE · -r / --resizefs vergrößert das Dateisystem gleich mit (fsadm, also resize2fs oder xfs_growfs).' }],
  lvreduce: [{ sek: 8, kurz: 'Reduce the size of a logical volume', text: '-L 20G / -L -5G. Ohne -r wird das Dateisystem NICHT verkleinert: Daten gehen verloren. Mit -r hängt fsadm aus, prüft und verkleinert ext vorher. XFS lässt sich nicht verkleinern.' }],
  lvresize: [{ sek: 8, kurz: 'Resize a logical volume', text: 'Vergrößert oder verkleinert, je nach -L. Sonst wie lvextend und lvreduce, auch mit -r.' }],
  lvrename: [{ sek: 8, kurz: 'Rename a logical volume', text: 'lvrename VG ALT NEU oder lvrename /dev/VG/ALT /dev/VG/NEU' }],
  lvremove: [{ sek: 8, kurz: 'Remove logical volume(s) from the system', text: 'lvremove VG/LV fragt bei aktiven LVs nach, -y bzw. -f ohne Rückfrage. Eingehängte LVs lassen sich nicht entfernen.' }],
  lvconvert: [{ sek: 8, kurz: 'Change logical volume layout', text: '--merge VG/SNAPSHOT führt einen Snapshot in sein Original zurück. Ist das Original geöffnet, geschieht das bei der nächsten Aktivierung.' }],
  lvm: [{ sek: 8, kurz: 'LVM2 tools', text: 'Gemeinsames Programm hinter pv*, vg* und lv*: lvm pvs entspricht pvs. lvm version zeigt die Versionen. Konfiguration: /etc/lvm/lvm.conf.' }],
  'lvm.conf': [{ sek: 5, kurz: 'Configuration file for LVM2', text: 'Abschnitte devices (filter = [ "a|/dev/sd.*|", "r|.*|" ] wählt Geräte aus), activation (snapshot_autoextend_threshold, snapshot_autoextend_percent), global. Prüfen: lvmconfig.' }],
  resize2fs: [{ sek: 8, kurz: 'ext2/ext3/ext4 file system resizer', text: 'resize2fs GERÄT füllt das Gerät aus (auch eingehängt). resize2fs GERÄT 20G verkleinert, aber nur ausgehängt und nach e2fsck -f.' }],
  xfs_growfs: [{ sek: 8, kurz: 'expand an XFS filesystem', text: 'xfs_growfs EINHÄNGEPUNKT vergrößert ein eingehängtes XFS auf die Größe des Geräts. Verkleinern geht bei XFS nicht.' }],
  hdparm: [{ sek: 8, kurz: 'get/set SATA/IDE device parameters', text: '-I Identify (Fähigkeiten, TRIM) · -i Kurzinfo · -t / -T Lesegeschwindigkeit · -W0/-W1 Schreibcache · -d1 DMA (nur alte IDE /dev/hd*) · -S N Standby-Zeit · -C Zustand · -y sofort Standby. Nicht für NVMe.' }],
  sdparm: [{ sek: 8, kurz: 'access SCSI modes pages; read VPD pages; send simple SCSI commands', text: 'sdparm GERÄT zeigt Mode Pages · --inquiry Kennungen (VPD) · --get=WCE / --set=WCE Schreibcache. Für SCSI, SAS, USB und iSCSI.' }],
  nvme: [{ sek: 1, kurz: 'NVM-Express user space tooling for Linux', text: 'nvme list · nvme id-ctrl /dev/nvme0 · nvme id-ns /dev/nvme0n1 · nvme smart-log /dev/nvme0 · nvme error-log /dev/nvme0' }],
  fstrim: [{ sek: 8, kurz: 'discard unused blocks on a mounted filesystem', text: 'fstrim -v EINHÄNGEPUNKT · -a alle eingehängten mit TRIM-Unterstützung · regelmäßig per fstrim.timer. Alternative: Einhängeoption discard.' }],
  iscsiadm: [{ sek: 8, kurz: 'open-iscsi administration utility', text: '-m discovery -t sendtargets -p IP · -m node (Liste) · -m node -T IQN -p IP --login / --logout · -m node -o update -n NAME -v WERT · -m session [-P 3]' }],
  'iscsid.conf': [{ sek: 5, kurz: 'open-iscsi default configuration', text: '/etc/iscsi/iscsid.conf: Vorgaben für neu gefundene Knoten. node.startup = automatic|manual · node.session.auth.authmethod = CHAP · node.session.auth.username/password. Die Knoten selbst liegen unter /etc/iscsi/nodes/.' }],
  scsi_id: [{ sek: 8, kurz: 'retrieve and generate a unique SCSI identifier', text: '/lib/udev/scsi_id -g -u -d /dev/sdX gibt die WWID aus, die udev für /dev/disk/by-id und Multipath nutzt.' }],
  lsscsi: [{ sek: 8, kurz: 'list SCSI devices (or hosts), list NVMe devices', text: '[Host:Kanal:Ziel:LUN] Typ Hersteller Modell Revision Gerät. -t zeigt den Transport, -i die WWID.' }],
  ip: [{ sek: 8, kurz: 'show / manipulate routing, network devices, interfaces and tunnels', text: 'ip [-4|-6] [-br] [-d] OBJEKT BEFEHL. Objekte: link (Schnittstellen: show, set dev X up|down|mtu N|name N|address MAC, add NAME type vlan|veth|dummy …, del), address (add|del CIDR dev X [label X:NAME]), route (add|del|replace ZIEL via GW [dev X] [metric N], get ADRESSE), neigh (show|add|replace|del|flush, lladdr MAC nud permanent), rule. Abkürzungen: ip a s, ip r, ip l, ip n.' }],
  ifconfig: [{ sek: 8, kurz: 'configure a network interface', text: 'Aus net-tools, veraltet. ifconfig [-a] [SCHNITTSTELLE] · ifconfig X ADRESSE netmask MASKE · ifconfig X up|down · Alias: ifconfig enp0s31f6:1 192.168.1.51 · zeigt nur die erste IPv4-Adresse ohne Label.' }],
  route: [{ sek: 8, kurz: 'show / manipulate the IP routing table', text: 'Aus net-tools. route -n · route add default gw GW · route add -net NETZ netmask MASKE gw GW · route del -net … · Flags: U aktiv, G über Gateway, H einzelner Rechner.' }],
  arp: [{ sek: 8, kurz: 'manipulate the system ARP cache', text: 'Aus net-tools. arp -n (Tabelle, ohne Namen) · arp -a (BSD-Stil) · arp -s ADRESSE MAC (fester Eintrag) · arp -d ADRESSE · arp -f [DATEI] liest /etc/ethers. Flags: C vollständig, M fest (permanent). Neuer: ip neigh.' }],
  ethers: [{ sek: 5, kurz: 'Ethernet address to IP number database', text: 'Eine Zeile je Rechner: MAC-ADRESSE ADRESSE-ODER-NAME. Wird von arp -f und von manchen Diensten gelesen, nicht automatisch vom Kernel.' }],
  ss: [{ sek: 8, kurz: 'another utility to investigate sockets', text: '-t TCP, -u UDP, -l nur lauschende, -a alle, -n numerisch, -p Prozess (root), -s Zusammenfassung. Filter: ss -tn dst 203.0.113.66, ss -tn sport = :22. Nachfolger von netstat.' }],
  netstat: [{ sek: 8, kurz: 'Print network connections, routing tables, interface statistics', text: 'Aus net-tools. -t -u -l -a -n -p wie bei ss · -r Routentabelle · -i Schnittstellen · -s Statistik je Protokoll.' }],
  lsof: [{ sek: 8, kurz: 'list open files', text: '-i [PROTO][@ADRESSE][:PORT] Netzwerk-Sockets, etwa lsof -i :22 oder lsof -i TCP -n · -p PID · -u BENUTZER · +D VERZEICHNIS · -n ohne Namensauflösung, -P Ports als Zahl.' }],
  ping: [{ sek: 8, kurz: 'send ICMP ECHO_REQUEST to network hosts', text: '-c ANZAHL · -i SEKUNDEN · -s GRÖSSE · -I SCHNITTSTELLE · -4/-6 · -M do (nicht fragmentieren, mit -s zur MTU-Suche). ping6 entspricht ping -6.' }],
  ping6: [{ sek: 8, kurz: 'send ICMP ECHO_REQUEST to network hosts (IPv6)', text: 'Heute ein Verweis auf ping -6.' }],
  nc: [{ sek: 1, kurz: 'arbitrary TCP and UDP connections and listens', text: 'nc RECHNER PORT verbindet · -z nur prüfen, -v ausführlich: nc -zv srv1 22 · -l -p PORT lauscht · -u UDP · -w SEKUNDEN Zeitlimit.' }],
  tcpdump: [{ sek: 8, kurz: 'dump traffic on a network', text: '-i SCHNITTSTELLE (any = alle) · -n keine Namen, -nn auch keine Portnamen · -c ANZAHL · -e MAC-Adressen · -w DATEI schreiben, -r DATEI lesen · -D Schnittstellen. Filter: host, src, dst, net, port, tcp, udp, icmp, arp, verbunden mit and, or, not und Klammern.' }],
  nmap: [{ sek: 1, kurz: 'Network exploration tool and security / port scanner', text: 'nmap RECHNER · -sT TCP-Connect, -sS SYN (root), -sU UDP · -p 22,80 · -sn nur Rechner finden · -sV Dienstversionen · -O Betriebssystem.' }],
  traceroute: [{ sek: 1, kurz: 'print the route packets trace to network host', text: 'Zeigt jeden Router auf dem Weg. * * * = keine Antwort. -n ohne Namen, -I ICMP statt UDP, -T TCP. traceroute6 bzw. traceroute -6 für IPv6. Ähnlich: tracepath, mtr.' }],
  traceroute6: [{ sek: 1, kurz: 'print the route packets trace to network host (IPv6)', text: 'Entspricht traceroute -6.' }],
  mtr: [{ sek: 8, kurz: 'a network diagnostic tool', text: 'Verbindet traceroute und ping: zeigt laufend Verlust und Laufzeit je Hop. --report (-r) einmal als Bericht, -c ANZAHL Runden, -n ohne Namen, -w breiter Bericht.' }],
  hostname: [{ sek: 1, kurz: 'show or set the system\'s host name', text: 'hostname zeigt den Namen · hostname NEU setzt ihn bis zum Neustart · -f voller Name · -I alle Adressen. Dauerhaft: /etc/hostname (Debian), /etc/HOSTNAME (ältere SUSE), hostnamectl set-hostname.' }],
  iw: [{ sek: 8, kurz: 'show / manipulate wireless devices and their configuration', text: 'iw dev · iw dev wlp2s0 link|info · iw dev wlp2s0 scan (root) · iw dev wlp2s0 connect SSID (nur offene Netze und WEP) · iw list (Fähigkeiten) · iw reg get|set DE. Nachfolger von iwconfig.' }],
  iwconfig: [{ sek: 8, kurz: 'configure a wireless network interface', text: 'Aus wireless-tools, veraltet. iwconfig [SCHNITTSTELLE] zeigt ESSID, Access Point, Signal · iwconfig wlp2s0 essid NAME · für WPA2 reicht es nicht, dafür wpa_supplicant.' }],
  iwlist: [{ sek: 8, kurz: 'Get more detailed wireless information from a wireless interface', text: 'Aus wireless-tools. iwlist wlp2s0 scan zeigt Zellen mit Address, Channel, ESSID, Encryption, Signal level. Neuer: iw dev wlp2s0 scan.' }],
  rfkill: [{ sek: 8, kurz: 'tool for enabling and disabling wireless devices', text: 'rfkill oder rfkill list zeigt Soft- und Hard-Block · rfkill unblock wifi|bluetooth|all|ID · rfkill block … Hard blocked = Schalter oder BIOS, lässt sich nicht per Software lösen.' }],
  wpa_supplicant: [{ sek: 8, kurz: 'Wi-Fi Protected Access client and IEEE 802.1X supplicant', text: 'wpa_supplicant -B -i wlp2s0 -c /etc/wpa_supplicant/wpa_supplicant.conf · -B im Hintergrund · -D nl80211 Treiber. Auf Debian auch als Unit wpa_supplicant@wlp2s0 mit /etc/wpa_supplicant/wpa_supplicant-wlp2s0.conf. Steuerung: wpa_cli.' }],
  'wpa_supplicant.conf': [{ sek: 5, kurz: 'configuration file for wpa_supplicant', text: 'ctrl_interface=DIR=/run/wpa_supplicant GROUP=netdev · network={ ssid="NAME" psk="Passwort" } oder psk=64 Hexzeichen aus wpa_passphrase · key_mgmt=WPA-PSK · priority=N.' }],
  wpa_passphrase: [{ sek: 8, kurz: 'Generate a WPA PSK from an ASCII passphrase for a SSID', text: 'wpa_passphrase SSID [PASSWORT] gibt einen network-Block aus, mit dem Passwort als Kommentar und dem PSK (PBKDF2, 4096 Runden) als psk=. Ohne Passwort liest es von der Standardeingabe. Den Kommentar besser löschen.' }],
  wpa_cli: [{ sek: 8, kurz: 'WPA command line client', text: 'wpa_cli [-i wlp2s0] status · list_networks · scan / scan_results · reconfigure (Datei neu lesen) · terminate.' }],
  dhclient: [{ sek: 8, kurz: 'Dynamic Host Configuration Protocol Client', text: 'dhclient [-v] SCHNITTSTELLE holt eine Adresse · -r gibt sie zurück · -1 nur ein Versuch. Leases: /var/lib/dhcp/dhclient.leases. Setzt die Standardroute ohne Metrik. Auf Red Hat übernimmt NetworkManager.' }],
  interfaces: [{ sek: 5, kurz: 'network interface configuration for ifup and ifdown', text: 'Debian: /etc/network/interfaces. auto enp3s0 · iface enp3s0 inet static (oder dhcp, manual) · address 10.20.0.23/16 · gateway … · up ip route add 10.30.0.0/16 via 10.20.0.1 · source /etc/network/interfaces.d/*. ifup/ifdown wenden es an.' }],
  'nm-settings-ifcfg-rh': [{ sek: 5, kurz: 'Description of ifcfg-rh settings plugin', text: 'Red Hat: /etc/sysconfig/network-scripts/ifcfg-NAME. DEVICE, BOOTPROTO=none|dhcp, IPADDR, PREFIX oder NETMASK, GATEWAY, DNS1, ONBOOT=yes. NetworkManager liest sie über das ifcfg-rh-Plugin, nach Änderungen nmcli connection reload. Ab RHEL 9 sind Keyfiles in /etc/NetworkManager/system-connections der Standard.' }],
  nmcli: [{ sek: 1, kurz: 'command-line tool for controlling NetworkManager', text: 'nmcli general · nmcli device [status|show|wifi list|wifi connect SSID password PW|disconnect X] · nmcli connection [show|up|down|add|modify|delete|reload] · nmcli radio wifi on|off. NetworkManager schreibt /etc/resolv.conf aus den Profilen neu.' }],
  'hosts.allow': [{ sek: 5, kurz: 'format of host access control files', text: '/etc/hosts.allow und /etc/hosts.deny: DIENST: CLIENTS [: OPTIONEN]. Zuerst hosts.allow, dann hosts.deny, sonst erlaubt. Gilt nur für Programme mit libwrap und für Dienste unter tcpd. Prüfen: tcpdmatch DIENST ADRESSE.' }],
  'resolv.conf': [{ sek: 5, kurz: 'resolver configuration file', text: 'nameserver ADRESSE (bis zu drei) · search DOMAIN… · domain DOMAIN · options timeout:2 attempts:2 rotate. Wird oft von NetworkManager, systemd-resolved oder dhclient erzeugt und dann überschrieben.' }],
  lspci: [{ sek: 8, kurz: 'list all PCI devices', text: '-k Kerneltreiber je Gerät · -v ausführlich · -nn Herstellernummern · -s BUS:GERÄT. Netzwerkkarten erscheinen als Ethernet controller oder Network controller.' }],
  smartctl: [{ sek: 8, kurz: 'Control and Monitor Utility for SMART Disks', text: '-i Info · -H Gesamturteil · -A Attribute · -a alles · -t short|long Selbsttest · -l selftest Ergebnisse.' }],
  'smartd.conf': [{ sek: 5, kurz: 'SMART Disk Monitoring Daemon Configuration File', text: 'Eine Zeile pro Gerät: /dev/sdb -a -m root -s (S/../.././02|L/../../6/03). DEVICESCAN = alle Geräte, folgende Zeilen werden ignoriert.' }],
  'auto.master': [{ sek: 5, kurz: 'Master Map for automounter consulted by autofs', text: 'EINHÄNGEPUNKT [MAPTYP:]MAP [OPTIONEN], etwa /mnt/labor /etc/auto.labor --timeout=60. /- bindet eine direkte Map ein. +dir:/etc/auto.master.d liest *.autofs.' }],
  autofs: [{ sek: 5, kurz: 'Format of the automounter maps', text: 'SCHLÜSSEL [-OPTIONEN] ORT. Lokal: daten -fstype=ext4 :/dev/sdb1. NFS: projekte -fstype=nfs4 srv1:/srv/projekte. Platzhalter: * srv1:/home/&.' }],
  automount: [{ sek: 8, kurz: 'manage autofs mount points', text: 'Läuft als Dienst autofs. automount -m zeigt die geladenen Maps. Nach Änderungen: systemctl reload autofs.' }],
  genisoimage: [{ sek: 1, kurz: 'create ISO9660/Joliet/HFS filesystem with optional Rock Ridge attributes', text: 'genisoimage -o BILD.iso [-R] [-J] [-V LABEL] [-b BOOT -c KATALOG -no-emul-boot] ORDNER. Auch als mkisofs aufrufbar.' }],
  mkisofs: [{ sek: 1, kurz: 'create ISO9660/Joliet/HFS filesystem with optional Rock Ridge attributes', text: 'Unter Debian ein Link auf genisoimage. -R Rock Ridge, -J Joliet, -b El Torito, -hfs HFS.' }],
  isoinfo: [{ sek: 1, kurz: 'utility programs for dumping and verifying iso9660 images', text: 'isoinfo -d -i BILD.iso zeigt Bezeichnung und Erweiterungen (Joliet, Rock Ridge, El Torito). -f -i listet Dateien.' }],
  mkudffs: [{ sek: 8, kurz: 'create a Universal Disk Format filesystem', text: 'mkudffs [-l LABEL] GERÄT_ODER_DATEI. Einhängen mit mount -t udf.' }],
  cryptsetup: [{ sek: 8, kurz: 'manage plain dm-crypt, LUKS, and other encrypted volumes', text: 'luksFormat GERÄT · open GERÄT NAME (→ /dev/mapper/NAME) · close NAME · status NAME · luksDump GERÄT · luksAddKey/luksRemoveKey GERÄT · isLuks.' }],
  crypttab: [{ sek: 5, kurz: 'static information about encrypted filesystems', text: 'NAME GERÄT SCHLÜSSELDATEI OPTIONEN, etwa: tresor UUID=… none luks. none = beim Start nach der Passphrase fragen.' }],
  fallocate: [{ sek: 1, kurz: 'preallocate or deallocate space to a file', text: 'fallocate -l 2G DATEI legt eine Datei der Größe an, ohne Daten zu schreiben.' }],
  sync: [{ sek: 1, kurz: 'Synchronize cached writes to persistent storage', text: 'Schreibt alle gepufferten Daten auf die Datenträger.' }],
  ldconfig: [{ sek: 8, kurz: 'configure dynamic linker run-time bindings', text: 'Baut /etc/ld.so.cache. -p zeigt den Cache.' }],
};

// Diese Befehle sind in die Bash eingebaut und haben auf Debian keine eigene Handbuchseite.
export const EINGEBAUT_OHNE_SEITE = new Set(['cd', 'export', 'unset', 'set', 'alias', 'unalias', 'type', 'history', 'jobs', 'fg', 'bg', 'umask', 'source']);

export function whatis(name: string, sek?: number): string[] {
  return (SEITEN[name] ?? []).filter((s) => !sek || s.sek === sek).map((s) => `${(name + ' (' + s.sek + ')').padEnd(21)}- ${s.kurz}`);
}
export function apropos(wort: string): string[] {
  const re = new RegExp(wort.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
  return Object.entries(SEITEN).flatMap(([n, l]) => l.filter((s) => re.test(n) || re.test(s.kurz)).map((s) => `${(n + ' (' + s.sek + ')').padEnd(21)}- ${s.kurz}`)).sort();
}
